with with_gaps as (select *, case when lag(txn_time) over (partition by merchant order by txn_time asc, id asc) is null or txn_time > lag(txn_time) over (partition by merchant order by txn_time asc, id asc) + interval 7 days then 1 else 0 end as is_new_burst from transactions), islands as (select *, sum(is_new_burst) over (partition by merchant order by txn_time asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps) select case when amount >= 3400 then 'HIGH' else 'LOW' end as amount_tier, round(avg(island_id), 2) as avg_island_id, round(avg(is_new_burst), 2) as avg_is_new_burst, sort_array(collect_set(merchant)) as merchant_list, min(txn_time) as started_at from islands group by case when amount >= 3400 then 'HIGH' else 'LOW' end order by amount_tier desc nulls first;
